onClick:
{{
  Insert_Ligne_Location.run()
    .then(() => {
      // 1. Fermer la modale
      closeModal('modal_add_ligne');

      // 2. Réinitialiser les champs
      resetWidget('sel_article', true);
      resetWidget('inp_add_qte', true);

      // 3. Recharger la liste des articles et les totaux
      Get_Lignes_Location.run();
      Get_Location_Detail.run();

      // 4. Notification de confirmation
      showAlert('Article ajouté avec succès !', 'success');
    })
    .catch((err) => {
      showAlert("Erreur lors de l'ajout de l'article : " + err.message, 'error');
    });
}}
